 for p in (RAW.parent,OUT.parent,MASK.parent,CONTACT.parent,QA.parent,CAL.parent,PROMPT.parent): p.mkdir(parents=True,exist_ok=True)
 body=Image.open(BODY).convert('RGBA'); src=Image.open(SOURCE).convert('RGBA'); RAW.write_bytes(BODY.read_bytes()); PROMPT.write_text('Original cast_rightup_2 body only; character right hand is the screen-right fist around (190,187). Deterministic sword baseline: screen angle -90 degrees, handle point (190.57,186.59), no redraw or prior candidate input.\n',encoding='utf-8')
